insert into public.grammar_point_translations (grammar_point_id, locale, title, explanation)
select g.id, t.locale, t.title, t.explanation
from (values
  ('GR001', 'en', 'Subject forms', 'Who does something: ich, du, er, si, es, mir, ihr, si. The verb changes with the person: ich gang, du gaasch, mir gönd.'),
  ('GR002', 'en', '"mir" = we', 'In Swiss German, mir usually means we: Mir gönd hei = We''re going home. It can also mean (to) me, as in Standard German: Gib mir das. The verb tells you which: mir gönd (we) or gib mir (to me).'),
  ('GR003', 'en', 'Polite "Si"', 'Use Si with strangers, older people and at work: the people you greet with Grüezi. The verb takes its plural form: Händ Si Ziit? "(To) you" is Ine: Wie gaht''s Ine?'),
  ('GR004', 'en', 'Object forms', 'Who something happens to. In speech they''re usually short: mi (me), di (you), en (him), si (her, them), eus (us). Ich gseh di. Chasch mi abhole?'),
  ('GR005', 'en', 'Dative forms', 'To or for whom: mir, dir, ihm, ihre, eus, eu, ine. Ich gib dir s Buech. Also after verbs like hälfe: Chasch mir hälfe?'),
  ('GR001', 'de', 'Subjektformen', 'Wer etwas tut: ich, du, er, si, es, mir, ihr, si. Das Verb passt sich der Person an: ich gang, du gaasch, mir gönd.'),
  ('GR002', 'de', '«mir» = wir', 'Auf Schweizerdeutsch heisst mir meistens wir: Mir gönd hei = Wir gehen heim. Es kann aber wie im Hochdeutschen auch mir heissen: Gib mir das. Das Verb zeigt, was gemeint ist: mir gönd (wir) oder gib mir (mir).'),
  ('GR003', 'de', 'Höfliches «Si»', 'Si brauchst du bei Fremden, älteren Leuten und bei der Arbeit, also bei allen, die du mit Grüezi begrüsst. Das Verb steht in der Mehrzahl: Händ Si Ziit? «Ihnen» heisst Ine: Wie gaht''s Ine?'),
  ('GR004', 'de', 'Objektformen', 'Wen etwas betrifft. Gesprochen meist kurz: mi (mich), di (dich), en (ihn), si (sie), eus (uns). Ich gseh di. Chasch mi abhole?'),
  ('GR005', 'de', 'Dativformen', 'Wem etwas gilt: mir, dir, ihm, ihre, eus, eu, ine. Ich gib dir s Buech. Auch nach Verben wie hälfe: Chasch mir hälfe?')
) as t (point_code, locale, title, explanation)
join public.grammar_points g on g.code = t.point_code;

